import re
with open('snake_anthropic-claude-sonnet-5_01.html', 'r', encoding='utf-8') as f:
    html = f.read()

print("File length:", len(html))
m = re.search(r'<script>([\s\S]*?)</script>', html)
if not m:
    print("NO SCRIPT FOUND")
else:
    script = m.group(1)
    print("script length", len(script))
    with open('.tmp_snake_check.js', 'w', encoding='utf-8') as f:
        f.write(script)

# also check basic balance of braces/parens
def check_balance(s):
    stack = []
    pairs = {')':'(', ']':'[', '}':'{'}
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return len(stack) == 0

if m:
    print("balanced:", check_balance(script))
